import random,json
random.seed(12)
np=32;hub=32;n=33;C=list(range(np))
def make_roots(seed):
 random.seed(seed);roots={i:0 for i in range(np)};L={}
 for k in range(400):
  T=[]
  for v in range(1,np):T.append((random.randrange(v),v))
  root=random.randrange(np);w=random.randint(1,1000)
  adj={i:[] for i in range(np)}
  for a,b in T:adj[a].append(b);adj[b].append(a)
  st=[root];seen={root}
  while st:
   x=st.pop()
   for y in adj[x]:
    if y not in seen:
     seen.add(y);L[(x,y)]=L.get((x,y),0)+w;st.append(y)
  roots[root]+=w
 out=[0]*np;inn=[0]*np
 for (a,b),c in L.items():out[a]+=c;inn[b]+=c
 caps=[max(out[i],inn[i],1) for i in range(np)]
 return roots,caps
r1,e1=make_roots(1);r2,e2=make_roots(2)
# use a common base capacity max caps to allow both env fits
base=[max(a,b) for a,b in zip(e1,e2)]
load={'op':'load','n':n,'links':[[i,hub,base[i]] for i in range(np)],'bookings':[]}
p1={'op':'prepare','id':'A','owner':'o','window':[0,1000],'period':10,'participants':[[i,r1[i]] for i in range(np)],'envelope':[[i,e1[i]] for i in range(np)],'rev':0}
p2={'op':'prepare','id':'B','owner':'o','window':[0,2000],'period':20,'participants':[[i,r2[i]] for i in range(np)],'envelope':[[i,e2[i]] for i in range(np)],'rev':0}
with open('/workspace/tmp/trace_star2.jsonl','w') as f:
 for x in [load,p1,p2]:f.write(json.dumps(x,separators=(',',':'))+'\n')
